sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    /**
     * Displays the certificate renewal failure alert.
     * 
     * Sets the renew_alert state to show a critical error message
     * using pre-configured failure content. Clears any existing links.
     */

    const { header, message } = api.state.renew_alert_content.failure;

    api.setState('renew_alert', {
        ...api.state.renew_alert,
        type: 'critical',
        header,
        message,
        show: true,
        links: {}
    });
}
